        premIntl: { es: "−7.9%: LATAM +20.3% en pesos (+41.9% en dólares; Costa Rica +17%), QIC −77%.", en: "−7.9%: LATAM +20.3% in pesos (+41.9% in dollars; Costa Rica +17%), QIC −77%." },
