        totalEquity: { es: "Solvencia 314% (RCS Ps. 6,440 M) antes del dividendo de mayo; plusvalías no realizadas ≈Ps. 1.5 mil M.", en: "Solvency 314% (RCS Ps. 6,440 M) before the May dividend; unrealised gains ≈Ps. 1.5 bn." },
